+test("consume uses the batch that expires first (FEFO)", () => {
+  const store = fresh();
+  // Milk: lot HD-1022 (batch 4, 2 l) expires before lot HD-1026 (batch 3).
+  assert.deepEqual(consume(store, 2, 1, { at }), [{ batchId: 4, qty: 1 }]);
+  assert.deepEqual(consume(store, 2, 3, { at }), [
