+
+test("consume order: no expiry last, then received first, then lower id", () => {
+  const store = fresh();
+  const base = { itemId: 4, qty: 1, location: "dry" };
+  store.data.batches = [
+    { ...base, id: 101, lot: "A", receivedOn: "2026-10-01", expires: null },
+    { ...base, id: 102, lot: "B", receivedOn: "2026-10-05", expires: "2026-12-01" },
+    { ...base, id: 104, lot: "D", receivedOn: "2026-10-03", expires: "2026-12-01" },
+    { ...base, id: 103, lot: "C", receivedOn: "2026-10-03", expires: "2026-12-01" },
+    { ...base, id: 105, lot: "E", receivedOn: "2026-10-20", expires: "2026-11-10" },
